import React, { useEffect, useState } from 'react'
import './App.css'
import mockQuestions from './data'

function Quiz() {

  const [questions, setQuestions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [currentQuestion, setCurrentQuestion] = useState(1);
  const [selectAnswer, setSelectAnswer] = useState(null);
  const [showAnswer, setShowAnswer] = useState(false)
  const [score, setScore] = useState(0);


  useEffect(() => {
    const fetchQuestions = async () => {
      try {
        const res = await fetch('https://opentdb.com/api.php?amount=10')
        const data = await res.json();
        // console.log(data)
        // setQuestions(data.results);
        setQuestions(mockQuestions);
        setLoading(false);
      } catch (error) {
        console.log("Error Fetching Questions , using mock data", error)
        setQuestions(mockQuestions);
        setLoading(false);
      }
    }
    fetchQuestions();
  }, []);

  const handleAnswerClick = (answer) => {
    setSelectAnswer(answer);
    setShowAnswer(true);
  }


  if (loading) {
    return <h3>Loading Questions ...</h3>
  }
  const question = questions[currentQuestion]
  // console.log(question)
  const answers = [...question.incorrect_answers, question.correct_answer]
  return (
    <div className='quiz-container '>
      <p className='quiz-header'>Quiz Quest</p>
      <p className='score-display'>Score: {score}</p>
      {
        <div>
          <p className='question-text'>{question.question}</p>
          <div className='answers-container'>
            {answers.map((ans, index) => (
              <button key={index}
                className={`answer-button ${showAnswer ? (ans === question.correct_answer ? 'correct correct-text' : (ans === selectAnswer ? 'incorrect incorrect-text' : '')) : ''}`}
                onClick={() => handleAnswerClick(ans)}
              >{ans}</button>
            ))}
          </div>
          {showAnswer &&
            <p className={selectAnswer === question.correct_answer ? '' : ''}>
              {selectAnswer === question.correct_answer ? 'Correct Answer' : 'Incorect Answer'}
              </p>
          }
        </div>
      }
    </div>
  )
}

export default Quiz
